var ENT=[["Hugging Face Transformers", "The standard pretrained-model library."], ["Function calling", "Structured tool-use interfaces for models."], ["LiteLLM", "One interface for 100-plus LLM providers."], ["OpenRouter", "Unified gateway across model providers."], ["ONNX", "Open Neural Network Exchange: portable model format moving networks between frameworks."], ["llama.cpp", "C++ inference engine running large language models efficiently on CPUs."], ["Ollama", "A friendly local runner packaging models with Modelfiles for one-command serving."]];
